// Extract error details provided by n8n Error Trigger
const errorData = $input.first().json;

const executionId = errorData.execution?.id || 'UNKNOWN_EXECUTION';
const workflowName = errorData.workflow?.name || 'Lead Intake & Qualification Pipeline';
const errorMessage = errorData.execution?.error?.message || 'Unspecified runtime exception';
const errorNode = errorData.execution?.error?.node?.name || 'Unknown Node';
const timestamp = new Date().toISOString();

// Structured Alert Payload
const alertSummary = {
  event: 'WORKFLOW_EXECUTION_FAILURE',
  workflow: workflowName,
  execution_id: executionId,
  failed_node: errorNode,
  error_message: errorMessage,
  severity: 'CRITICAL',
  logged_at: timestamp
};

return [{
  json: {
    ...alertSummary,
    notification_message: `🚨 [CRITICAL ALERT] Workflow "${workflowName}" failed on Node [${errorNode}].\nExecution ID: ${executionId}\nError: ${errorMessage}\nTimestamp: ${timestamp}`
  }
}];
